def make_grid(H,W,rwalls,cwalls,markers):
    g=[[0]*W for _ in range(H)]
    for r in rwalls: g[r]=[8]*W
    for c in cwalls:
        for r in range(H): g[r][c]=8
    rb=[-1]+rwalls+[H]; cb=[-1]+cwalls+[W]
    for color,ri,ci in markers:
        r=rb[ri]+1; c=cb[ci]+1; g[r][c]=color
    return g

